number = int(input(), 16)
for multiplier in range(1, 16):
    print(f"{number:X}*{multiplier:X}={number * multiplier:X}")

n = int(input())
for number in range(1, n + 1):
    print("X" if number % 10 in (3, 6, 9) else number, end=" ")

r, g, b = map(int, input().split())
for red in range(r):
    for green in range(g):
        for blue in range(b):
            print(red, green, blue)
print(r * g * b)

n = int(input())
for number in range(1, n + 1):
    if number % 3 == 0:
        continue
    print(number, end=" ")

board = [list(map(int, input().split())) for _ in range(19)]
n = int(input())
for _ in range(n):
    row, col = map(int, input().split())
    row -= 1
    col -= 1
    for i in range(19):
        board[row][i] = 1 - board[row][i]
    for i in range(19):
        board[i][col] = 1 - board[i][col]
for row in board:
    print(*row)

h, w = map(int, input().split())
board = [[0] * w for _ in range(h)]
n = int(input())
for _ in range(n):
    length, direction, row, col = map(int, input().split())
    row -= 1
    col -= 1
    for offset in range(length):
        if direction == 0:
            board[row][col + offset] = 1
        else:
            board[row + offset][col] = 1
for row in board:
    print(*row)

board = [list(map(int, input().split())) for _ in range(10)]
row, col = 1, 1
while True:
    found = board[row][col] == 2
    board[row][col] = 9
    if found:
        break
    if board[row][col + 1] != 1:
        col += 1
    elif board[row + 1][col] != 1:
        row += 1
    else:
        break
for line in board:
    print(*line)
